CREATE DEFINER=`root`@`localhost` PROCEDURE `REPORTE_ASISTENCIAS`(
    IN DEPARTAMENTO VARCHAR(100),
    IN DESDE DATE,
    IN HASTA DATE
)
BEGIN
    SELECT 
        e.id AS idEmpleado,
        e.nombre,
        e.apellidoPaterno,
        e.apellidoMaterno,
        d.nombre AS departamento,
        es.tipo,
        es.fecha,
        es.hora
    FROM entrada_salida es
    INNER JOIN empleados e 
        ON es.nombre COLLATE utf8mb4_general_ci = e.nombre COLLATE utf8mb4_general_ci
    INNER JOIN departamentos d 
        ON e.idDepartamento = d.id
    WHERE (DEPARTAMENTO = 'TODOS' 
           OR d.nombre COLLATE utf8mb4_general_ci = DEPARTAMENTO COLLATE utf8mb4_general_ci)
      AND es.fecha BETWEEN DESDE AND HASTA
    ORDER BY e.id, es.fecha, es.hora;
END ;;
DELIMITER ;
