CREATE DEFINER=`root`@`localhost` PROCEDURE `REPORTE_EMPLEADO`(
    IN TIPO_EMPLEADO VARCHAR(100),
    IN DEPARTAMENTO VARCHAR(100),
    IN ESTATUS_EMPLEADO VARCHAR(100)
)
BEGIN
    SELECT 
        e.id,
        e.nombre,
        e.apellidoPaterno,
        e.apellidoMaterno,
        te.nombre AS tipoEmpleado,
        ee.nombre AS estatusEmpleado,
        d.nombre AS departamento,
        e.fechaNacimiento,
        e.domicilio,
        e.telefono,
        e.curp,
        e.observaciones
    FROM empleados e
    INNER JOIN tiposempleados te ON e.idTipoEmpleado = te.id
    INNER JOIN estatusempleados ee ON e.idEstatusEmpleado = ee.id
    INNER JOIN departamentos d ON e.idDepartamento = d.id
   WHERE (TIPO_EMPLEADO = 'TODOS' OR te.nombre COLLATE utf8mb4_general_ci = TIPO_EMPLEADO COLLATE utf8mb4_general_ci)
  AND (DEPARTAMENTO = 'TODOS' OR d.nombre COLLATE utf8mb4_general_ci = DEPARTAMENTO COLLATE utf8mb4_general_ci)
  AND (ESTATUS_EMPLEADO = 'TODOS' OR ee.nombre COLLATE utf8mb4_general_ci = ESTATUS_EMPLEADO COLLATE utf8mb4_general_ci);

END ;;
DELIMITER ;
