DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `REPORTE_INCIDENCIAS`(
IN nombreCompleto VARCHAR(100) 
)
BEGIN
    SELECT 
        i.id,
        CONCAT(
            e.nombre COLLATE utf8mb4_general_ci, ' ', 
            e.apellidoPaterno COLLATE utf8mb4_general_ci, ' ', 
            e.apellidoMaterno COLLATE utf8mb4_general_ci
        ) AS nombreCompleto,
        t.nombre COLLATE utf8mb4_general_ci AS tipoIncidencia,
        i.fechaHoraInicio,
        i.fechaHoraFin,
        i.observaciones
    FROM incidencias i
    INNER JOIN empleados e ON i.idEmpleado = e.id
    INNER JOIN tiposincidencias t ON i.idTipoIncidencia = t.id
    WHERE (nombreCompleto = 'TODOS'
           OR CONCAT(e.nombre COLLATE utf8mb4_general_ci, ' ', e.apellidoPaterno COLLATE utf8mb4_general_ci, ' ', e.apellidoMaterno COLLATE utf8mb4_general_ci) = nombreCompleto)
    ORDER BY i.fechaHoraInicio ASC;
END ;;
DELIMITER ;
